Use graph.authoring(snapshotKey) for new response drafts with stable local keys. Give graph-authoring native children this recipe and the exact supplied import URL. Choose new snapshots for new accepted explanations. This runnable example shows early publication, further work, and final submission. Replace its placeholder evidence with actual task findings; do not publish an empty progress message.

```javascript
import { RelayerGraphClient, GraphApiError, NodeObject, html, css, detailCapability } from "GRAPH_CLIENT_MODULE_URL";
const graph = RelayerGraphClient.fromEnv();
let current;
try { current = await graph.getCurrent(); }
catch (error) {
  if (!(error instanceof GraphApiError) || error.code !== "feature_disabled") throw error;
  current = null; // Supported all-off compatibility mode: submit the final graph directly.
}
const contract = await graph.getContract();
async function stageResponseLinks(responseLayer) {
  for (const requirement of contract?.returnRequirements ?? []) {
    if (requirement.kind !== "navigate.response") throw new Error("Unsupported Return requirement");
    const snapshot = await graph.getNodePresentation(requirement.nodeId);
    const addition = { kind: "navigate", relation: "reference", label: "Task findings", target: responseLayer, clientKey: "response-INTERACTION_NODE_ID-" + requirement.nodeId };
    await graph.addAction(requirement.nodeId, addition);
    if (snapshot.node.authoredDetail) {
      const prior = snapshot.node;
      const additions = new NodeObject(prior.icon, prior.title, prior.detail, prior.kind, prior.clientKey);
      additions.detailAuthoring.setComponent("response-INTERACTION_NODE_ID", html`<button gc=${detailCapability.reference("response-control", addition)}>Task findings</button>`);
      // The typed extension retains all accepted components, assets and control provenance.
      await graph.extendNodePresentation(requirement.nodeId, snapshot.revision, additions);
    }
  }
}
const author = graph.authoring("first-finding-INTERACTION_NODE_ID");
const layer = author.layer("finding");
const sharedStyles = css`section { display: grid; gap: 0.75rem; background-color: transparent; }`;
// The current closure preserves prior publications even after later Advances.
// Completion-specific keys avoid matching another interaction's accepted findings.
const pending = current?.currentLayerId == null ? [] : [current.currentLayerId];
const visited = new Set();
let firstPublished = false;
while (pending.length > 0) {
  const id = pending.pop();
  if (visited.has(id)) continue;
  visited.add(id);
  const published = await graph.getLayer(id);
  if (published.layer.state !== "accepted") throw new Error("Current history must be accepted");
  if (published.layer.clientKey === layer.object.clientKey) { firstPublished = true; break; }
  for (const action of published.actions) {
    if (action.kind === "navigate" && action.targetLayerId != null) pending.push(action.targetLayerId);
  }
}
// Skip every write in the committed phase; repair only the remaining drafts.
if (current !== null && !firstPublished) {
  const finding = layer.node("finding", { icon: "info", title: "Initial finding", detail: "Replace with supported evidence, remaining uncertainty, and the next useful step." });
  // This optional detail example demonstrates typed control binding, not required topology.
  const evidenceLayer = author.layer("evidence");
  const evidence = evidenceLayer.node("evidence", { icon: "info", title: "Evidence", detail: "Replace with useful support for the finding." });
  const expand = layer.action("evidence", finding, { kind: "navigate", relation: "expand", label: "Evidence", target: evidenceLayer });
  finding.detailAuthoring.setComponent("main", html`<section><h2>Initial finding</h2><p>Replace with supported evidence and uncertainty.</p><button gc=${detailCapability.expand("evidence-control", expand)}>Evidence</button></section>`, sharedStyles);
  evidence.detailAuthoring.setComponent("main", html`<section><h2>Evidence</h2><p>Replace with useful supporting detail.</p></section>`, sharedStyles);
  evidenceLayer.layout([[evidence, 0.5, 0.5]], { edgeShape: "default", defaultNode: evidence });
  if (current.currentLayerId != null) {
    const prior = await graph.getLayer(current.currentLayerId);
    const earlier = layer.action("prior", finding, { kind: "navigate", relation: "reference", label: "Earlier findings", target: prior.layer });
    finding.detailAuthoring.setComponent("earlier", html`<button gc=${detailCapability.reference("earlier-control", earlier)}>Earlier findings</button>`, sharedStyles);
  }
  layer.layout([[finding, 0.5, 0.5]], { edgeShape: "default", defaultNode: finding });
  const written = await author.write(layer);
  await graph.addAction(INTERACTION_NODE_ID, { kind: "navigate", relation: "expand", label: "Task findings", icon: "info", target: written.rootLayer, clientKey: "root-response" });
  await stageResponseLinks(written.rootLayer);
  await graph.advanceCurrent(written.rootLayer, current.headRevision, "first-finding-publication");
}
// Continue the underlying work. Read evidence and observe any semantic children.
// Publish further material findings or questions as new snapshots, preserving prior current.
if (current !== null) current = await graph.getCurrent();
const finalAuthor = graph.authoring("final-findings");
// This example relates a result to its reasoning and evidence; it is not a node quota.
// Choose the actual task's relationships. An atomic answer can remain one node.
const finalLayer = finalAuthor.layer("summary");
const summary = finalLayer.node("summary", { icon: "info", title: "Result", detail: "Replace with the completed result or the consequential question requiring the user's answer." });
const reasoning = finalLayer.node("reasoning", { icon: "info", title: "Why this follows", detail: "Replace with the material reason, mechanism or tradeoff that explains this result." });
const verification = finalLayer.node("verification", { icon: "info", title: "Evidence and limits", detail: "Replace with observed checks, sources or worked examples, and the limits of what they establish." });
finalLayer.edge("result-reasoning", summary, reasoning);
finalLayer.edge("result-verification", summary, verification);
const supportLayer = finalAuthor.layer("supporting-evidence");
const support = supportLayer.node("support", { icon: "info", title: "Supporting evidence", detail: "Replace with the actual check output, source extract or worked example supporting the result; distinguish observations from interpretation." });
const inspectSupport = finalLayer.action("inspect-support", verification, { kind: "navigate", relation: "expand", label: "Inspect supporting evidence", target: supportLayer });
summary.detailAuthoring.setComponent("main", html`<section><h2>Result</h2><p>Replace with the completed result or consequential question.</p></section>`, sharedStyles);
reasoning.detailAuthoring.setComponent("main", html`<section><h2>Why this follows</h2><p>Replace with the material reasoning behind the result.</p></section>`, sharedStyles);
verification.detailAuthoring.setComponent("main", html`<section><h2>Evidence and limits</h2><p>Replace with observed support and remaining limits.</p><button gc=${detailCapability.expand("support-control", inspectSupport)}>Inspect supporting evidence</button></section>`, sharedStyles);
support.detailAuthoring.setComponent("main", html`<section><h2>Supporting evidence</h2><p>Replace with concrete evidence that adds depth beyond the root.</p></section>`, sharedStyles);
supportLayer.layout([[support, 0.5, 0.5]], { edgeShape: "default", defaultNode: support });
if (current?.currentLayerId != null) {
  const prior = await graph.getLayer(current.currentLayerId);
  const earlier = finalLayer.action("prior", summary, { kind: "navigate", relation: "reference", label: "Earlier findings", target: prior.layer });
  summary.detailAuthoring.setComponent("history", html`<button gc=${detailCapability.reference("earlier-control", earlier)}>Earlier findings</button>`, sharedStyles);
}
finalLayer.layout([[summary, 0.5, 0.25], [reasoning, 0.25, 0.72], [verification, 0.75, 0.72]], { edgeShape: "default", defaultNode: summary });
const finalWritten = await finalAuthor.write(finalLayer);
// Advance leaves the interaction's root response action draft; retarget that same stable action.
await graph.addAction(INTERACTION_NODE_ID, { kind: "navigate", relation: "expand", label: "Task findings", icon: "info", target: finalWritten.rootLayer, clientKey: "root-response" });
await stageResponseLinks(finalWritten.rootLayer);
await graph.submit(INTERACTION_NODE_ID);
```
Add a connection with layer.edge("connection", first, second). Declare node controls before write with layer.action("details", node, { kind: "navigate", relation: "expand", label: "Details", target: childLayer }); bind that same returned action with detailCapability.expand("stable-control-key", action) in an unquoted gc= template interpolation, as shown above. The key and action are both required. For references use relation: "reference" and detailCapability.reference; for follow-ups use kind: "invoke", interactionText, and detailCapability.invoke. layer.node(localKey, fields) accepts only icon, title, detail, and optional kind: do not pass clientKey or ref in fields. layer.action(localKey, sourceNode, fields) supplies sourceLayer, clientKey, and ref: do not author these fields. Declare actions before binding them, and reuse the returned action without cloning or adding identity fields. Set each selected layer's layout explicitly, including routes or sizeJustification when needed, with layer.layout(...); written.rootLayer is available only after author.write(...), and has no .layer wrapper. For specialized low-level calls, layer.object is the actual LayerObject. Accepted-node additions and replacements still use their existing authorized low-level APIs and presentation revisions.
The example reads the sealed contract and stages every required attached-node link to each exact candidate response root, including the final retarget. For rich accepted nodes, the typed presentation extension preserves existing components, assets and controls while compiling the new control. Advance validates these staged changes but only Return publishes them. Use unique component/control keys; stale revisions and extension conflicts require rereading or an explicit full replacement, never dropping existing content. The example probes current before writing. Only a typed feature_disabled rejection selects the submit-only compatibility path. Other errors propagate. On rerun while active, the completion-specific first-layer key in the reachable current closure identifies an already published phase (including after later advances); skip its writes and Advance, then repair only the final drafts. Do not rerun after a successful or unknown terminal submission; terminal recovery belongs to trusted supervision.
For real content, use the same scoped action and detailCapability binding APIs as the ordinary authoring contract. Register every action before publication. Accepted nodes and layers stay immutable. Each later current must retain navigation to the exact prior current. Refresh getCurrent after each successful advance; save each transition's layer, expected headRevision and stable operation key for exact retries. When asking a question, author an input action on its draft explanation node with layer.action("question", finding, { kind: "input", label: "Answer", control: "text", prompt: "A task-specific question" }), or an appropriate select control. Publishing the question does not consume the user's answer. A terminal submit ends all graph access.
If the existing published Current is the intended final response, all Return requirements already target it, and no unfinished drafts remain, run only this alternative finalization program. A fresh client can finish it without reconstructing any accepted objects. For changed content use a new snapshot instead. Do not run this after a successful or unknown terminal outcome.

```javascript
import { RelayerGraphClient } from "GRAPH_CLIENT_MODULE_URL";
const graph = RelayerGraphClient.fromEnv();
const published = await graph.getCurrent();
if (published.currentLayerId == null || published.lifecycle !== "active") throw new Error("No active published response");
await graph.returnCurrent(published.currentLayerId, published.headRevision, "finish-published-current");
// Terminal: no further graph reads or writes.
```
Repair authoring without losing the task's intended controls. Preserve the question when repairing its control: text Input mounts on textarea (or a supported text input), never button; explicit Answer is provided by the runtime. External links use a typed externalLink binding, never raw href. The following fragment uses the existing author, layer and finding objects; choose a consequential task-specific question and an actual source URL in sourceUrl. Include it only when the task needs these controls.

```javascript
const question = layer.action("question", finding, { kind: "input", label: "Answer", control: "text", prompt: "Which constraint should guide the next step?" });
finding.detailAuthoring.setComponent("question", html`<p>The next step depends on your constraint; independent evidence gathering can continue.</p><label>Constraint<textarea aria-label="Constraint" gc=${detailCapability.input("question-control", question)}></textarea></label><a gc=${detailCapability.externalLink("source-link", sourceUrl)}>Source</a>`);
```

For a new artifact destination, declare it in this same authoring scope. For example, const viewer = author.layer("itinerary-viewer"); viewer.artifactNode("itinerary", { icon: "box", title: "Itinerary", detail: "Shareable itinerary", artifact: { kind: "markdown", source: { file: "itinerary.md" } } }); layer.action("itinerary", finding, { kind: "navigate", relation: "expand", label: "Open itinerary", target: viewer });. artifactNode supplies the one-node artifact layout. The file must exist before writing. Do not link a scoped draft to an independently submitted draft LayerObject; published destinations require an explicit accepted layer record.
Before Advance or Return, connect every intended draft layer through the response root; explicitly discard abandoned drafts with await graph.discardLayer(abandonedLayer). A successful author.write persists drafts, not Current. Register the response root and its actions, then Advance before continuing work. For a human-root question, run the reply-reading example below while active; keep its cursor across reads. Inspect each returned question and value, and use them in the dependent result. Empty replies do not authorize assumptions. If no answer arrives, finish with the useful question and unresolved dependency instead of waiting indefinitely. Repair the specific rejected component and retain its valid Input/navigation actions; do not silently delete the question to obtain acceptance.
After publishing a consequential human-root Input with Advance, read replies while the completion is active. Here question and finding are the exact Input declaration and owning node from the example above. Resolve the accepted action by its owner and stable clientKey, never its label or position; clientKey alone is only source-node scoped. A fresh client must recover those exact accepted identities. Each later question needs its own published occurrence. This example allows up to 30 seconds for a participant response; choose a bounded window appropriate to the task and remaining time. A short empty poll is not a completed opportunity to answer. Do independent work while waiting when possible, then reread before settling dependent work. Retain nextSequence across reads; a fresh process may recover from zero, but only a receipt for this exact question occurrence satisfies this wait. Earlier questions' receipts do not. Read each matching answer's question and value before using it. No answer means unresolved, not permission to invent a preference.

```javascript
let answerCursor = 0;
const answeringCurrent = await graph.getCurrent();
const answeringLayer = await graph.getLayer(answeringCurrent.currentLayerId);
const answeringAction = answeringLayer.actions.find(action => action.kind === "input" && action.clientKey === question.clientKey && action.sourceNodeId === finding.ref.id);
if (!answeringAction) throw new Error("The intended question is not published in Current");
const answersThisQuestion = answer => answer.occurrence.presentingInteractionNodeId === answeringCurrent.completionId
  && answer.occurrence.presentingLayerId === answeringCurrent.currentLayerId
  && answer.occurrence.actionId === answeringAction.id;
const answerDeadline = Date.now() + 30_000;
let replies = await graph.getLiveAnswers(answerCursor);
answerCursor = replies.nextSequence;
let questionAnswers = replies.answers.filter(answersThisQuestion);
while (questionAnswers.length === 0 && replies.current.lifecycle === "active" && Date.now() < answerDeadline) {
  replies = await graph.waitForLiveAnswers(answerCursor, Math.max(0, answerDeadline - Date.now()));
  answerCursor = replies.nextSequence;
  questionAnswers = replies.answers.filter(answersThisQuestion);
}
const userDecisions = questionAnswers.map(answer => ({ question: answer.question, value: answer.value }));
// Use userDecisions in dependent work; publish changed findings with a new snapshot.
```


Read current with let current = await graph.getCurrent(). The first current layer may contain visible accepted nodes; when no prior current exists, it needs no new draft carrier. When a prior current exists, every later current layer and the root of your final graph.submit must retain a navigation path back to that prior current. Reuse an existing valid path when one already exists; otherwise, after submitting the new layer and before publishing it, add a reference navigate action from one of its draft nodes created for this interaction to current.currentLayerId. Reuse alone grants no action authority; the exact frozen attached-node navigation exception is described above. Give each distinct logical advanceCurrent transition its own stable operation key. Save that transition's exact layer, expected headRevision, and operation key together. Before every Advance, author or retarget the interaction's one root navigate/expand action to that candidate layer using its same stable clientKey. All CompletionContract returnRequirements must already be satisfied, including staged attached-node links to that exact response layer. After submitting the complete closure and registering all its actions, publish it with await graph.advanceCurrent(layer, expectedHeadRevision, operationKey). An exact retry reuses all three unchanged. After a successful nonterminal advanceCurrent, refresh with current = await graph.getCurrent() before building the next logical transition, so its revision and backreference use the new current. Use a different stable key for that next transition. A successful terminal graph.submit ends graph access: do not call getCurrent or perform any further graph reads or writes afterward.

The current interaction may carry an invoke lease created by the product. Before authoring, use graph.getNode(INTERACTION_NODE_ID) and graph.getNeighbors(INTERACTION_NODE_ID) to inspect the current node and any relevant source context exposed by the graph. Treat that context as input to your answer; do not copy, forge, or manage lease metadata. Author the response normally. A successful ordinary graph.submit(INTERACTION_NODE_ID) automatically fulfills any lease held by this interaction. There is no separate resolveAction call.


Graph search is available through the same executable JavaScript client as await graph.search(request, options). It is not a provider-native tool or MCP function. The public request accepts queryContractVersion, query, optional tagged parameters, optional budget, and an optional target: { scope: "thread" | "project", id: positiveInteger }. Omit target to search the current interaction's thread. Supply target only when the product or user has already provided the exact canonical ID, for example target: { scope: "project", id: knownProjectId }. Never invent, guess, or discover a target ID. The selector chooses a dataset; it is not authority, and Rust still intersects it with the completion-bound read permit. Never add raw permit, credential, token, database, candidate-source, or other authority fields. Search sees accepted published graph records only; it never exposes drafts and never falls back to SQLite when the Ladybug index is unavailable.

Use queryContractVersion: 1. The admitted read-only query profile supports whole-target Content or Layer scans and bounded one- or two-relationship MATCH patterns over CONNECTED, CONTAINS, EXPANDS, and REFERENCES. It does not support mutation, procedures, arbitrary-length paths, or more than two hops. Put values in tagged parameters instead of query literals, for example parameters: { anchor: { type: "string", value: "Queue" }, count: { type: "integer", value: "2" } }. Integers are signed 64-bit decimal strings, not JavaScript numbers. Results also use tagged values: null, boolean, integer, float, string, node, layer, relationship, path, homogeneous list, or ordered record. Without a smaller LIMIT, search returns at most 5 rows; LIMIT above the hard maximum of 8 is rejected, and the complete encoded result is bounded to 16 KiB. A successful prefix reports truncated: true when another whole row exists beyond a row or byte bound.

Content.title is the exact canonical Node title, not a section heading inside authored HTML. For an exact title lookup, use the actual title from an accepted Node you have inspected. If known completion/history pointers identify the relevant work, read its layer or node and inspect its detail to resolve a requested section to that Node's title. Use identities supplied by those pointers or successful scoped reads; never infer an identity from a title. Discovery searches remain useful when the relevant Node is unknown.

When the goal is a Layer reference, project the Layer alone and read it to inspect the content. Reuse a successful, untruncated result that already identifies the needed Layer; do not repeat a search merely to remove extra projection columns. Empty, truncated or ambiguous results may require refinement or a scoped pointer read. They do not prove absence, and they never justify inventing a target identity.

The following example uses inspectedNode, an accepted Node already read with graph.getNode or graph.getLayer and inspected for relevance.

For example:
const search = await graph.search({ queryContractVersion: 1, query: "MATCH (l:Layer)-[:CONTAINS]->(n:Content) WHERE n.title = $anchor RETURN l AS layer ORDER BY layer ASC", parameters: { anchor: { type: "string", value: inspectedNode.title } } });

Graph search contract failures are GraphQueryError values with stable status, code, phase, and path fields; message wording is explanatory and may change. Branch on code or phase, never on message text. Transport or index unavailability is a GraphApiError rather than a stale successful result. Pass { signal } as the second graph.search argument when cancellation matters.

A returned graph value is data, not authority. When search finds accepted context that materially supports the current response, add a typed reference action from a node in the new layer. Require a tagged layer value, validate its public identity, convert only its positive safe numeric suffix, and let graph.addAction revalidate visibility:
const priorLayer = search.rows[0]?.[0];
if (search.truncated) throw new Error("Graph search results are truncated; narrow the query before selecting a layer");
if (priorLayer?.type !== "layer") throw new Error("Expected a tagged layer search result");
const priorLayerMatch = /^layer:([1-9][0-9]*)$/.exec(priorLayer.id);
const priorLayerId = priorLayerMatch === null ? NaN : Number(priorLayerMatch[1]);
if (!Number.isSafeInteger(priorLayerId)) throw new Error("Expected a safe accepted layer identity");
await graph.addAction(summaryNode, { kind: "navigate", relation: "reference", sourceLayer: currentLayer, label: "View prior context", target: priorLayerId, clientKey: "summary-prior-context" });
Do not turn a node, relationship, path, list, record, or arbitrary string into an action target. Search is optional: use it when prior accepted graph context can improve the answer, not as a substitute for inspecting the workspace or completing the underlying task.

Navigation has two meanings:
- "expand" continues the explanation with a more detailed layer. Expansion must not point back to an expansion ancestor.
- "reference" opens supporting evidence or context. References may reuse an accepted layer, may point to other reference layers, and may revisit a layer.

The interaction node must have one root navigate action with relation: "expand" and no sourceLayer. Every action on a response node must include sourceLayer: the LayerObject in which you are authoring that action. Expansion layers may author expand, reference, or invoke actions. A layer reached as a reference may author only reference actions. Do not create both expand and reference actions to the same new target layer.

Examples:
await graph.addAction(INTERACTION_NODE_ID, { kind: "navigate", relation: "expand", label: "Key findings", icon: "search", target: rootLayer, clientKey: "root-response" });
await graph.addAction(node, { kind: "navigate", relation: "expand", sourceLayer: rootLayer, label: "Explain further", target: detailLayer, clientKey: "node-detail" });
await graph.addAction(node, { kind: "navigate", relation: "reference", sourceLayer: rootLayer, label: "View evidence", target: evidenceLayer, clientKey: "node-evidence" });
await graph.addAction(node, { kind: "invoke", sourceLayer: rootLayer, label: "Follow up", interactionText: "Ask a useful follow-up", clientKey: "node-follow-up" });

For every layer, choose the member whose detail should open first. Set layer.defaultNode to that NodeObject before submitLayer. Make this choice intentionally for the task; it does not change graph position or node order. The UI uses it only when there is no remembered user selection.

Layers normally contain 1 to 5 nodes. A layer may contain 6 to 8 nodes only when keeping them together matters; pass a private sizeJustification to submitLayer. Never mention or expose the size justification in user-facing node text. More than 8 nodes must be split. Layer edges are visible and undirected. Every node needs a supported icon, short title, and useful markdown detail. Choose recognizable icons for the subject using agent judgment. Familiar supported symbol strings remain valid without lookup. Discover symbols or registered images with graph.icons.discover({query, kind: "both", limit: 12}) in JavaScript or await graph.icons.discover(query, kind="both", limit=12) in Python. Filter kind with symbols/images/both; copy a returned item's icon into a node or action. Results are compact, bounded catalog metadata, separate from conversation Content. Optional graph.icons.inspect([item.icon], {contactSheet: true}) / await graph.icons.inspect([item["icon"]], contact_sheet=True) returns preview files or a small numbered contact sheet; native image inspection depends on the harness/model. Use meaningful symbols when communicative and sourced image assets for recognizable organisms, objects, logos, or other subjects. Register image bytes through visualAssets.add / visual_assets.add with name, description, and tags, then use {kind: "image", assetId: asset.id}; accepted output pins registered bytes. Image icons default to contain and preserve transparency; optionally set fit: "cover" and framing: "none" | "circle" | "rounded". Signal symbols describe status, warnings, confirmations, or pointers rather than the node's subject. Static Node Detail images use imageIconDetail(icon) / image_icon_detail(icon), or existing assetRef bindings. For a static bundled symbol, await symbolIconDetail(graph, "waves") / await symbol_icon_detail(graph, "waves") registers its pinned SVG preview in the current scope and returns the same ordinary image component. Pass the returned html and css to the node Detail builder.

Every new root, expansion, and reference layer requires a version-1 LayerLayoutObject(placements, edgeShape, edgeRoutes?) with exactly one NodePlacementObject(node, x, y) per member node. Coordinates are normalized numbers from 0 through 1 and express semantic relative position independently of the viewport. Place a one-node layer at (0.5, 0.5). Keep flow or time moving consistently, use a parent or summary node to anchor hierarchy, group related nodes spatially, align comparisons deliberately, and avoid accidental overlap or edge crossings where a clearer arrangement is available. Do not use pixels, window size, or inspector state. Example: const layout = new LayerLayoutObject([new NodePlacementObject(first, 0.25, 0.5), new NodePlacementObject(second, 0.75, 0.5)], "elbow-horizontal"); const layer = new LayerObject([first, second], [edge], layout); a routed loop-back: new LayerLayoutObject(placements, "elbow-horizontal", [{ edge: loopBack, ends: [{ node: last, side: "top" }, { node: first, side: "top" }], waypoints: [{ x: 0.9, y: 0.1 }, { x: 0.1, y: 0.1 }] }]);
Every layer layout also names the layer's edge shape, which draws all of its edges: one of "default", "straight", "arc-outward", "arc-circle", "elbow-horizontal", "elbow-vertical". Edges never show a direction. Choose the shape from the layer's structure:
- "default": no strong structural reason; the design chooses.
- "arc-outward": a hub and its spokes, or loose relationships around a centre.
- "arc-circle": a cycle, or a ring of peers that each connect to their neighbours.
- "elbow-horizontal": a left-to-right pipeline or sequence of stages.
- "elbow-vertical": a top-down hierarchy or breakdown.
- "straight": comparisons, grids, or dense layers.
List the placements in reading order; keyboard and screen-reader users follow that order. Position the nodes so they read in that order too, and for an elbow shape run the reading order along its axis: left to right for "elbow-horizontal", top to bottom for "elbow-vertical".
Edge routes are optional and most layers need none. Add a route only for an edge the layer's shape would draw badly: a loop-back along a row of nodes, an edge that skips a node, or one that would cross another node. A route may give that one edge its own shape, the side of each of its two nodes where it attaches ("top", "right", "bottom", "left"), and up to 4 waypoints: layout coordinates from 0 through 1 that the edge passes through, listed from the route's first end to its second. Try sides first; for example, attach both ends of a loop-back at "top" to arc it over the row. Pick sides that face where the edge goes. Add waypoints only when sides are not enough. A route's ends are just the edge's two nodes, not a direction.

Artifacts: when your work produced something the user should see as itself, such as a website, a PDF, a video, an image, a Markdown or Office document in the thread folder, or a deployed site, give it an artifact layer. Relayer opens that layer full screen in its artifact viewer instead of a graph. Create the files first, then author the artifact node and its layer, and open the layer from an ordinary node with a navigate action:
const site = new NodeObject("globe", "Landing page", "The launch site. Check the pricing section on a phone.", "concept", "landing-page");
site.artifact = { kind: "website", source: { file: "site/index.html", root: "site" }, part: { route: "#pricing" }, viewport: "phone" };
await graph.submitNode(site);
const siteViewer = LayerObject.forArtifact(site, "landing-page-viewer");
await graph.submitLayer(siteViewer);
await graph.addAction(overviewNode, { kind: "navigate", relation: "expand", sourceLayer: rootLayer, label: "Open the site", target: siteViewer, variant: "pill", clientKey: "open-landing-page" });
Kinds: "website" (an entry .html file plus its site root folder), "pdf", "video" (.mp4, .webm, .mov), "image" (.png, .jpg, .gif, .webp, .svg), "markdown" (.md), "docx", "xlsx" and "pptx" (Office), and "url" (https, or http only on localhost). File paths are relative to the thread folder and must stay inside it. A part opens the artifact at one place: a route for websites, web apps and URLs ("/pricing", "#/cart"), a page for PDFs (from 1), start and end seconds for a video segment, a heading for Markdown, or a slide for a deck. A viewport ("desktop", "tablet", "phone") applies to websites, web apps and URLs only. Show two views of one artifact as two artifact nodes, each in its own artifact layer. An artifact layer holds exactly that one node and no edges; never put an artifact node in a graph layer. Relayer fingerprints the files when you submit the node and again when your answer is accepted. A web app you can run, such as a dev server, is kind "app": source.url is its loopback address (http://127.0.0.1:5173/), and server names the command that starts it in the thread folder: { command: "npm run dev", readyUrl: "http://127.0.0.1:5173/" (optional, defaults to source.url), idleTimeoutMinutes: 60 (optional) }. When the user opens it, Relayer reuses a server that already answers, or runs the command after the user approves it once per thread, so you need not leave a server running. A website or web app may set a starting state that Relayer applies on every open: seed: { localStorage: { "cart": "[]" } }, and for web apps also cookies: [{ name: "session", value: "demo-user" }]. Seeds hold test values only, never real credentials or personal data. Office documents are kind "docx" (Word), "xlsx" (Excel) or "pptx" (PowerPoint); a deck can open at a slide (part: { slide: 3 }, from 1). Save spreadsheets with their calculated values, for example by recalculating in LibreOffice before you finish, because Relayer shows saved values and never recalculates: formulas without them render blank. Charts in a deck may draw wrongly, so export a PDF next to any deck with charts and point the artifact at the PDF. The node's title names the artifact; its detail says what it is and what to look at. Make artifact layers only for things the user should look at, not for every file you touched.

Layer edges are exactly what the user sees and are undirected. Every node needs a supported icon, a short title, and useful markdown detail. Optional action icons must also use a supported Relayer icon name:
Choose recognizable icons for the subject using agent judgment. Familiar supported symbol strings remain valid without lookup. Discover symbols or registered images with graph.icons.discover({query, kind: "both", limit: 12}) in JavaScript or await graph.icons.discover(query, kind="both", limit=12) in Python. Filter kind with symbols/images/both; copy a returned item's icon into a node or action. Results are compact, bounded catalog metadata, separate from conversation Content. Optional graph.icons.inspect([item.icon], {contactSheet: true}) / await graph.icons.inspect([item["icon"]], contact_sheet=True) returns preview files or a small numbered contact sheet; native image inspection depends on the harness/model. Use meaningful symbols when communicative and sourced image assets for recognizable organisms, objects, logos, or other subjects. Register image bytes through visualAssets.add / visual_assets.add with name, description, and tags, then use {kind: "image", assetId: asset.id}; accepted output pins registered bytes. Image icons default to contain and preserve transparency; optionally set fit: "cover" and framing: "none" | "circle" | "rounded". Signal symbols describe status, warnings, confirmations, or pointers rather than the node's subject. Static Node Detail images use imageIconDetail(icon) / image_icon_detail(icon), or existing assetRef bindings. For a static bundled symbol, await symbolIconDetail(graph, "waves") / await symbol_icon_detail(graph, "waves") registers its pinned SVG preview in the current scope and returns the same ordinary image component. Pass the returned html and css to the node Detail builder.

Action variants are "chip", "pill", "wide", or "card". A card requires description; other variants do not accept one.

The graph service enforces exact provenance, target visibility, layer size, expansion cycles, and accepted closure. If a call fails, read every natural-language issue, repair only unaccepted draft phases; skip every phase already accepted by Advance. Edit the remaining program and rerun it with the same clientKey values. Preserve the supplied import URL byte for byte and use a single-quoted shell heredoc. For a rejected draft, rebuild fresh objects with the same scoped snapshot/local keys. Rerun graph authoring only after an explicit repairable graph rejection, without repeating completed workspace effects. If submission succeeded, or its response was lost and the outcome is unknown, let the host recover the persisted outcome. Stable keys make a rerun, whole or edited, update the same drafts instead of creating duplicates when each object's identity-owning context stays unchanged. An action's clientKey is scoped to its source node: keep every draft action on the same source node during repair, because moving it creates a different action and leaves the original draft behind. Do not add fake navigate or reference actions merely to make abandoned draft layers reachable. Only when Advance or terminal submission identifies a genuinely abandoned orphan draft, recover with graph.discardLayer(layer); this preserves that layer as stopped history without discarding its nodes, edges, actions, or child layers. A model turn ending is not completion. A successful terminal submit or Return is required to complete the GraphComplete response, but it does not by itself complete the underlying user task. Do not submit a plan as though it were completed work. Before final submission, verify that requested workspace effects have actually occurred and represent their real results in the graph.
